function setBits(a, b) {
  if (typeof a !== "string" || typeof b !== "string" ||
      a.length !== b.length || !/^[01]*$/.test(a) ||
      !/^[01]*$/.test(b)) {
    throw new TypeError("Use equal-length bit strings");
  }
  let complement = "", union = "", intersection = "";
  let difference = "", symmetric = "";
  for (let i = 0; i < a.length; i++) {
    const x = a[i] === "1", y = b[i] === "1";
    complement += Number(!x);
    union += Number(x || y);
    intersection += Number(x && y);
    difference += Number(x && !y);
    symmetric += Number(x !== y);
  }
  return {complement, union, intersection, difference, symmetric};
}

function invertPermutation(values) {
  if (!Array.isArray(values)) {
    throw new TypeError("Use an array of images");
  }
  const n = values.length;
  const inverse = Array(n).fill(0);
  for (let i = 0; i < n; i++) {
    const y = values[i];
    if (!Number.isInteger(y) || y < 1 || y > n ||
        inverse[y - 1] !== 0) {
      throw new TypeError("Images must be 1 through n, each once");
    }
    inverse[y - 1] = i + 1;
  }
  return inverse;
}
